const input = $json || {};

const sampleQueue = [
  {
    dispatchId: 'dsp_sample_1',
    chatId: '1938141471',
    text: 'Add International Social Mixer to calendar?\n\nApprove / Reject / Alternative',
    parseMode: 'Markdown',
    buttons: [
      { label: 'Approve', value: 'approve:social-1-calendar-2' },
      { label: 'Reject', value: 'reject:social-1-calendar-2' },
      { label: 'Alternative', value: 'alternative:social-1-calendar-2' }
    ],
    scheduledFor: null,
    approvalId: 'apr_sample_123',
    relatedActionId: 'social-1-calendar-2'
  }
];

let telegramQueue = [];

if (Array.isArray(input.telegramQueue)) {
  telegramQueue = input.telegramQueue;
} else if (Array.isArray(input.result?.channelDispatch?.telegramQueue)) {
  telegramQueue = input.result.channelDispatch.telegramQueue;
} else if (
  Array.isArray(
    input.channelDispatcherOutput?.result?.channelDispatch?.telegramQueue
  )
) {
  telegramQueue =
    input.channelDispatcherOutput.result.channelDispatch.telegramQueue;
} else {
  telegramQueue = sampleQueue;
}

return [{
  json: {
    telegramQueue,
    metadata: {
      correlationId:
        input.metadata?.correlationId ||
        `telegram-${Date.now()}`,
      dispatchEnabled:
        input.metadata?.dispatchEnabled === true,
      testMode:
        input.metadata?.testMode ?? true,
      ...input.metadata
    }
  }
}];

const queue = Array.isArray($json.telegramQueue)
  ? $json.telegramQueue
  : [];

const metadata = $json.metadata || {};
const output = [];

for (let index = 0; index < queue.length; index++) {
  const item = queue[index] || {};
  const chatId = item.chatId ? String(item.chatId) : '';
  const baseText = String(item.text || '').trim();

  if (!chatId || !baseText) {
    output.push({
      json: {
        valid: false,
        shouldSend: false,
        error: !chatId ? 'missing_chat_id' : 'missing_text',
        dispatchId: item.dispatchId || null,
        metadata
      }
    });
    continue;
  }

  const buttonLines =
    Array.isArray(item.buttons) && item.buttons.length
      ? '\n\n' +
        item.buttons
          .map(button => `${button.label}: ${button.value}`)
          .join('\n')
      : '';

  output.push({
    json: {
      valid: true,
      shouldSend: metadata.dispatchEnabled === true,
      dispatchId:
        item.dispatchId ||
        `telegram-dispatch-${Date.now()}-${index + 1}`,
      chatId,
      text: `${baseText}${buttonLines}`.slice(0, 4000),
      parseMode: item.parseMode || 'Markdown',
      approvalId: item.approvalId || null,
      relatedActionId: item.relatedActionId || null,
      scheduledFor: item.scheduledFor || null,
      metadata
    }
  });
}

if (!output.length) {
  return [{
    json: {
      valid: false,
      shouldSend: false,
      error: 'empty_telegram_queue',
      metadata
    }
  }];
}

return output;

const original = $('Expand Telegram Queue').item.json || {};
const telegramResponse = $json || {};

return [{
  json: {
    success: true,
    result: {
      mode: 'sent',
      status: 'sent',
      dispatchId: original.dispatchId || null,
      chatId: original.chatId || null,
      approvalId: original.approvalId || null,
      relatedActionId: original.relatedActionId || null,
      telegramResponse
    },
    memoryUpdates: [{
      type: 'dispatch_history',
      operation: 'append',
      payload: {
        dispatchId: original.dispatchId || null,
        channel: 'telegram',
        destination: original.chatId || null,
        status: 'sent',
        createdAt: new Date().toISOString()
      }
    }],
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Telegram Channel Connector',
      level: 'info',
      correlationId: original.metadata?.correlationId || '',
      message: 'Telegram message sent.',
      details: {
        dispatchId: original.dispatchId || null,
        chatId: original.chatId || null
      }
    }],
    nextAction: {
      type: 'await_user_response',
      targetWorkflow: 'Concierge OS - Telegram Approval Response'
    },
    error: null
  }
}];

const item = $json || {};

return [{
  json: {
    success: item.valid === true,
    result: {
      mode: 'preview',
      status: item.valid ? 'preview_ready' : 'rejected',
      dispatchId: item.dispatchId || null,
      chatId: item.chatId || null,
      text: item.text || '',
      approvalId: item.approvalId || null,
      relatedActionId: item.relatedActionId || null,
      reason:
        item.valid
          ? 'dispatchEnabled is false'
          : item.error || 'invalid_payload'
    },
    memoryUpdates:
      item.valid
        ? [{
            type: 'dispatch_history',
            operation: 'append',
            payload: {
              dispatchId: item.dispatchId || null,
              channel: 'telegram',
              destination: item.chatId || null,
              status: 'preview_ready',
              createdAt: new Date().toISOString()
            }
          }]
        : [],
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Telegram Channel Connector',
      level: item.valid ? 'info' : 'warning',
      correlationId: item.metadata?.correlationId || '',
      message:
        item.valid
          ? 'Telegram payload prepared in preview mode.'
          : 'Telegram payload rejected.',
      details: {
        dispatchId: item.dispatchId || null,
        error: item.error || null
      }
    }],
    nextAction: {
      type: item.valid ? 'review_preview' : 'stop',
      targetWorkflow: null
    },
    error:
      item.valid
        ? null
        : {
            code: item.error || 'INVALID_TELEGRAM_PAYLOAD',
            message: 'Telegram payload is invalid.',
            retryable: false
          }
  }
}];
